def process_orders(orders):
    total = 0.0
    failed = []
    for order in orders:
        oid = None
        try:
            oid = order.get("id")
            amt = order.get("amount")
            qty = order.get("quantity")
            if oid is None or amt is None or qty is None:
                raise ValueError
            val = float(amt) * int(qty)
            if val != val or val < 0:
                raise ValueError
            total += val
        except Exception:
            if oid is not None:
                failed.append(oid)
            continue
    return {"revenue": total, "failed_orders": failed}
